{
  "reviews": [
    {
      "benchmark": "arc",
      "instrument_review": {
        "method": "Complete EFPA Test Review Model 2025, version 5.0, applied to the supplied ARC-AGI-2 passage.",
        "scope": "ARC-AGI-2 public test problems, official scoring software, and ARC Prize rules for evaluations it runs or verifies. Other evaluation routes may differ.",
